/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A finite form. A reflexive verb's form comes without its pronoun (`lavarsi` → `lavo`, as in `mi lavo`).
    Form(crate::Tense, crate::Person, crate::Number),
    /// The affirmative imperative (`prendi`, `prenda`, `prendiamo`, `prendete`, `prendano`).
    Imperative(crate::Addressee),
    /// The negative imperative, written after `non` (`non prendere`).
    NegativeImperative(crate::Addressee),
    /// The infinitive.
    Infinitive,
    /// The gerund (`prendendo`).
    Gerund,
    /// A participle (the past participle in the masculine singular; [`agreeing_participle`] makes it agree).
    Participle(crate::Participle),
}

impl Cell {
    /// Its place in a paradigm: its group's first cell, then its values
    /// counted in order, the last fastest.
    pub const fn index(self) -> usize {
        match self {
            Cell::Form(tense, person, number) => {
                cell::PRES_1_SG as usize
                    + (tense as usize * 3 + person as usize) * 2
                    + number as usize
            }
            Cell::Imperative(addressee) => cell::IMPERATIVE_TU as usize + addressee as usize,
            Cell::NegativeImperative(addressee) => {
                cell::NEGATIVE_IMPERATIVE_TU as usize + addressee as usize
            }
            Cell::Infinitive => cell::INFINITIVE as usize,
            Cell::Gerund => cell::GERUND as usize,
            Cell::Participle(participle) => cell::PARTICIPLE_PRES as usize + participle as usize,
        }
    }
}

impl From<(crate::Tense, crate::Person, crate::Number)> for Cell {
    fn from((tense, person, number): (crate::Tense, crate::Person, crate::Number)) -> Self {
        Cell::Form(tense, person, number)
    }
}

impl From<crate::Participle> for Cell {
    fn from(participle: crate::Participle) -> Self {
        Cell::Participle(participle)
    }
}

/// A verb to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verb<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    inherent: Vec<(u8, u8)>,
}

impl<'w> Verb<'w> {
    /// The verb `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Verb {
            lemma,
            given: Vec::new(),
            inherent: Vec::new(),
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its auxiliary: only conjugations of words of that auxiliary are read.
    #[must_use]
    pub fn auxiliary(mut self, auxiliary: crate::Auxiliary) -> Self {
        self.inherent.push((0, auxiliary as u8));
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &self.inherent,
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The conjugations it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn conjugation(&self) -> Vec<Reading<'static, 'static, Conjugation>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
